import { createMemo, createSignal } from 'solid-js';

const SIZE = 4;

export function App() {
  const [color, setColor] = createSignal('tomato');
  const style = createMemo(() => ({ color: color() }));
  const padding = createMemo(() => SIZE * 2);

  return (
    <p style={style()} onClick={() => setColor('teal')}>
      padding: {padding()}px
    </p>
  );
}

